node << 'EOF'
const http = require('http');
const https = require('https');

function checkEndpoint(url) {
  return new Promise((resolve) => {
    const protocol = url.startsWith('https') ? https : http;
    const startTime = Date.now();

    const request = protocol.get(url, { timeout: 5000 }, (response) => {
      let data = '';

      response.on('data', (chunk) => {
        data += chunk;
      });

      response.on('end', () => {
        const elapsed = Date.now() - startTime;
        resolve({
          url: url,
          status: response.statusCode,
          statusMessage: response.statusMessage,
          headers: response.headers,
          body: data.substring(0, 300),
          elapsed: elapsed,
          success: true
        });
      });
    });

    request.on('error', (error) => {
      const elapsed = Date.now() - startTime;
      resolve({
        url: url,
        status: null,
        error: error.message,
        elapsed: elapsed,
        success: false
      });
    });

    request.on('timeout', () => {
      request.destroy();
      const elapsed = Date.now() - startTime;
      resolve({
        url: url,
        status: null,
        error: 'Request timeout',
        elapsed: elapsed,
        success: false
      });
    });
  });
}

async function runChecks() {
  console.log('='.repeat(70));
  console.log('SERVICE DEPENDENCY HEALTH CHECK');
  console.log('='.repeat(70));
  console.log('');

  const endpoints = [
    'http://localhost:3003/checkConnectivity?variant=1',
    'https://httpstat.us/200'
  ];

  for (let i = 0; i < endpoints.length; i++) {
    const endpoint = endpoints[i];
    console.log(`Endpoint ${i + 1}: ${endpoint}`);
    console.log('-'.repeat(70));

    const result = await checkEndpoint(endpoint);

    if (result.success) {
      console.log(`✓ Status: ${result.status} ${result.statusMessage}`);
      console.log(`  Response Time: ${result.elapsed}ms`);
      console.log(`  Response Preview: ${result.body.substring(0, 150)}`);
    } else {
      console.log(`✗ Status: FAILED`);
      console.log(`  Error: ${result.error}`);
      console.log(`  Response Time: ${result.elapsed}ms`);
    }
    console.log('');
  }

  console.log('='.repeat(70));
  console.log('CHECK COMPLETED');
  console.log('='.repeat(70));
}

runChecks();
EOF
